import numpy as np, pandas as pd, warnings
from darts import TimeSeries
import darts.metrics as m
from darts.metrics.utils import register_metric_callback, unregister_metric_callback
a=TimeSeries.from_values(np.array([[1.],[2.],[3.]]))
p=TimeSeries.from_values(np.array([[1.],[4.],[3.]]))
# callback
calls=[]
def cb(**kw): calls.append(kw)
register_metric_callback(cb)
try: m.mae(a,p)
finally: unregister_metric_callback(cb)
print('callback keys', callbacks:=sorted(calls[0]), 'func',calls[0]['func'].__name__,'result',calls[0]['result'])
# NaN union
an=TimeSeries.from_values(np.array([[1.],[np.nan],[3.],[4.]]))
pn=TimeSeries.from_values(np.array([[1.],[2.],[np.nan],[2.]]))
for f in ['mae','wmape','r2_score']:
 try: print(f,m.__getattribute__(f)(an,pn))
 except Exception as e: print(f,type(e).__name__,e)
# safe divide zero percentage & scaled
z=TimeSeries.from_values(np.array([[0.],[0.],[0.]]))
nz=TimeSeries.from_values(np.array([[1.],[2.],[3.]]))
for f in ['mape','ape','smape','wmape','ope','arre','r2_score','coefficient_of_variation']:
 for args in [(z,z),(z,nz)]:
  try:
   with warnings.catch_warnings(record=True) as w:
    warnings.simplefilter('always'); r=getattr(m,f)(*args)
   print(f,'zero' if args[1] is z else 'nonzero',r,'warns',len(w))
  except Exception as e: print(f,type(e).__name__,e)
# autc validation
for kw in [{},{'min_tolerance':-0.1},{'min_tolerance':0.2,'max_tolerance':0.1},{'step':0},{'step':2}]:
 try:
  x=TimeSeries.from_values(np.array([[1.],[2.],[3.]])); print('autc',kw,m.autc(x,x,**kw))
 except Exception as e: print('autc',kw,type(e).__name__,e)
PY"}

